@Test
public void testSeek() throws Exception {
    // Seek to position 0
    int pos = 0;
    seekAndVerify(pos);
    Assert.assertEquals("ChunkIndex is incorrect", 0, blockInputStream.getChunkIndex());
    pos = CHUNK_SIZE;
    seekAndVerify(pos);
    Assert.assertEquals("ChunkIndex is incorrect", 1, blockInputStream.getChunkIndex());
    pos = (CHUNK_SIZE * 5) + 5;
    seekAndVerify(pos);
    Assert.assertEquals("ChunkIndex is incorrect", 5, blockInputStream.getChunkIndex());
    try {
        // Try seeking beyond the blockSize.
        pos = blockSize + 10;
        seekAndVerify(pos);
        Assert.fail("Seek to position beyond block size should fail.");
    } catch (EOFException e) {
        // Expected
    }
    // Seek to random positions between 0 and the block size.
    Random random = new Random();
    for (int i = 0; i < 10; i++) {
        pos = random.nextInt(blockSize);
        seekAndVerify(pos);
    }
}

@Test
public void testBlockEOF() throws Exception {
    // Seek to some position < blockSize and verify EOF is not reached.
    seekAndVerify(CHUNK_SIZE);
    Assert.assertFalse(blockInputStream.blockStreamEOF());
    // Seek to blockSize-1 and verify that EOF is not reached as the chunk
    // has not been read from container yet.
    seekAndVerify(blockSize - 1);
    Assert.assertFalse(blockInputStream.blockStreamEOF());
}

@Test
public void testGetAllPropertiesByTags() throws Exception {
    File coreDefault = tempConfigs.newFile("core-default-test.xml");
    File coreSite = tempConfigs.newFile("core-site-test.xml");
    try (BufferedWriter out = new BufferedWriter(new FileWriter(coreDefault))) {
        startConfig(out);
        appendProperty(out, "hadoop.tags.system", "YARN,HDFS,NAMENODE");
        appendProperty(out, "hadoop.tags.custom", "MYCUSTOMTAG");
        appendPropertyByTag(out, "dfs.cblock.trace.io", "false", "YARN");
        appendPropertyByTag(out, "dfs.replication", "1", "HDFS");
        appendPropertyByTag(out, "dfs.namenode.logging.level", "INFO", "NAMENODE");
        appendPropertyByTag(out, "dfs.random.key", "XYZ", "MYCUSTOMTAG");
        endConfig(out);
        Path fileResource = new Path(coreDefault.getAbsolutePath());
        conf.addResource(fileResource);
        Assert.assertEquals(conf.getAllPropertiesByTag("MYCUSTOMTAG").getProperty("dfs.random.key"), "XYZ");
    }
    try (BufferedWriter out = new BufferedWriter(new FileWriter(coreSite))) {
        startConfig(out);
        appendProperty(out, "dfs.random.key", "ABC");
        appendProperty(out, "dfs.replication", "3");
        appendProperty(out, "dfs.cblock.trace.io", "true");
        endConfig(out);
        Path fileResource = new Path(coreSite.getAbsolutePath());
        conf.addResource(fileResource);
    }
    // Test if values are getting overridden even without tags being present
    Assert.assertEquals("3", conf.getAllPropertiesByTag("HDFS").getProperty("dfs.replication"));
    Assert.assertEquals("ABC", conf.getAllPropertiesByTag("MYCUSTOMTAG").getProperty("dfs.random.key"));
    Assert.assertEquals("true", conf.getAllPropertiesByTag("YARN").getProperty("dfs.cblock.trace.io"));
}

