/**
 * Following test checks that chooseRandom works for excluded nodes, scope
 * and ancestor generation.
 */
@Test
public void testChooseRandomWithAffinityNode() {
    int[] excludedNodeIndexs = { 0, dataNodes.length - 1, random.nextInt(dataNodes.length), random.nextInt(dataNodes.length) };
    Node[][] excludedNodeLists = { {}, { dataNodes[0] }, { dataNodes[dataNodes.length - 1] }, { dataNodes[random.nextInt(dataNodes.length)] }, { dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)] }, { dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)] } };
    int[] affinityNodeIndexs = { 0, dataNodes.length - 1, random.nextInt(dataNodes.length), random.nextInt(dataNodes.length) };
    int leafNum = cluster.getNumOfLeafNode(null);
    Map<Node, Integer> frequency;
    String scope;
    for (int k : affinityNodeIndexs) {
        for (int i : excludedNodeIndexs) {
            String path = dataNodes[i].getNetworkFullPath();
            while (!path.equals(ROOT)) {
                int ancestorGen = cluster.getMaxLevel() - 1;
                while (ancestorGen > 0) {
                    for (Node[] list : excludedNodeLists) {
                        List<Node> excludedList = Arrays.asList(list);
                        frequency = pickNodes(leafNum, path, excludedList, dataNodes[k], ancestorGen);
                        Node affinityAncestor = dataNodes[k].getAncestor(ancestorGen);
                        for (Node key : dataNodes) {
                            if (affinityAncestor != null) {
                                if (frequency.get(key) > 0) {
                                    assertTrue(affinityAncestor.isAncestor(key));
                                } else if (!affinityAncestor.isAncestor(key)) {
                                    continue;
                                } else if (excludedList != null && excludedList.contains(key)) {
                                    continue;
                                } else if (path != null && key.getNetworkFullPath().startsWith(path)) {
                                    continue;
                                } else {
                                    fail("Node is not picked when sequentially going " + "through ancestor node's leaf nodes. node:" + key.getNetworkFullPath() + ", ancestor node:" + affinityAncestor.getNetworkFullPath() + ", excludedScope: " + path + ", " + "excludedList:" + (excludedList == null ? "" : excludedList.toString()));
                                }
                            }
                        }
                    }
                    ancestorGen--;
                }
                path = path.substring(0, path.lastIndexOf(PATH_SEPARATOR_STR));
            }
        }
    }
    // all nodes excluded, no node will be picked
    List<Node> excludedList = Arrays.asList(dataNodes);
    for (int k : affinityNodeIndexs) {
        for (int i : excludedNodeIndexs) {
            String path = dataNodes[i].getNetworkFullPath();
            while (!path.equals(ROOT)) {
                scope = "~" + path;
                int ancestorGen = 0;
                while (ancestorGen < cluster.getMaxLevel()) {
                    frequency = pickNodesAtRandom(leafNum, scope, excludedList, dataNodes[k], ancestorGen);
                    for (Node key : dataNodes) {
                        assertTrue(frequency.get(key) == 0);
                    }
                    ancestorGen++;
                }
                path = path.substring(0, path.lastIndexOf(PATH_SEPARATOR_STR));
            }
        }
    }
    // no node excluded and no excluded scope, each node will be picked
    int ancestorGen = cluster.getMaxLevel() - 1;
    for (int k : affinityNodeIndexs) {
        while (ancestorGen > 0) {
            frequency = pickNodes(leafNum, null, null, dataNodes[k], ancestorGen);
            Node affinityAncestor = dataNodes[k].getAncestor(ancestorGen);
            for (Node key : dataNodes) {
                if (frequency.get(key) > 0) {
                    if (affinityAncestor != null) {
                        assertTrue(affinityAncestor.isAncestor(key));
                    }
                }
            }
            ancestorGen--;
        }
    }
    // check invalid ancestor generation
    try {
        cluster.chooseRandom(null, null, null, dataNodes[0], cluster.getMaxLevel());
        fail("ancestor generation exceeds max level, should fail");
    } catch (Exception e) {
        assertTrue(e.getMessage().startsWith("ancestorGen " + cluster.getMaxLevel() + " exceeds this network topology acceptable level"));
    }
}

@Test
public void testCost() {
    // network topology with default cost
    List<NodeSchema> schemas = new ArrayList<>();
    schemas.add(ROOT_SCHEMA);
    schemas.add(RACK_SCHEMA);
    schemas.add(NODEGROUP_SCHEMA);
    schemas.add(LEAF_SCHEMA);
    NodeSchemaManager manager = NodeSchemaManager.getInstance();
    manager.init(schemas.toArray(new NodeSchema[0]), true);
    NetworkTopology newCluster = new NetworkTopologyImpl(manager);
    Node[] nodeList = new Node[] { createDatanode("1.1.1.1", "/r1/ng1"), createDatanode("2.2.2.2", "/r1/ng1"), createDatanode("3.3.3.3", "/r1/ng2"), createDatanode("4.4.4.4", "/r2/ng1") };
    for (Node node : nodeList) {
        newCluster.add(node);
    }
    Node outScopeNode1 = createDatanode("5.5.5.5", "/r2/ng2");
    Node outScopeNode2 = createDatanode("6.6.6.6", "/r2/ng2");
    assertEquals(Integer.MAX_VALUE, newCluster.getDistanceCost(nodeList[0], null));
    assertEquals(Integer.MAX_VALUE, newCluster.getDistanceCost(null, nodeList[0]));
    assertEquals(Integer.MAX_VALUE, newCluster.getDistanceCost(outScopeNode1, nodeList[0]));
    assertEquals(Integer.MAX_VALUE, newCluster.getDistanceCost(nodeList[0], outScopeNode1));
    assertEquals(Integer.MAX_VALUE, newCluster.getDistanceCost(outScopeNode1, outScopeNode2));
    assertEquals(0, newCluster.getDistanceCost(null, null));
    assertEquals(0, newCluster.getDistanceCost(nodeList[0], nodeList[0]));
    assertEquals(2, newCluster.getDistanceCost(nodeList[0], nodeList[1]));
    assertEquals(4, newCluster.getDistanceCost(nodeList[0], nodeList[2]));
    assertEquals(6, newCluster.getDistanceCost(nodeList[0], nodeList[3]));
    // network topology with customized cost
    schemas.clear();
    schemas.add(new NodeSchema.Builder().setType(NodeSchema.LayerType.ROOT).setCost(5).build());
    schemas.add(new NodeSchema.Builder().setType(NodeSchema.LayerType.INNER_NODE).setCost(3).build());
    schemas.add(new NodeSchema.Builder().setType(NodeSchema.LayerType.INNER_NODE).setCost(1).build());
    schemas.add(new NodeSchema.Builder().setType(NodeSchema.LayerType.LEAF_NODE).build());
    manager = NodeSchemaManager.getInstance();
    manager.init(schemas.toArray(new NodeSchema[0]), true);
    newCluster = new NetworkTopologyImpl(manager);
    for (Node node : nodeList) {
        newCluster.add(node);
    }
    assertEquals(Integer.MAX_VALUE, newCluster.getDistanceCost(nodeList[0], null));
    assertEquals(Integer.MAX_VALUE, newCluster.getDistanceCost(null, nodeList[0]));
    assertEquals(Integer.MAX_VALUE, newCluster.getDistanceCost(outScopeNode1, nodeList[0]));
    assertEquals(Integer.MAX_VALUE, newCluster.getDistanceCost(nodeList[0], outScopeNode1));
    assertEquals(Integer.MAX_VALUE, newCluster.getDistanceCost(outScopeNode1, outScopeNode2));
    assertEquals(0, newCluster.getDistanceCost(null, null));
    assertEquals(0, newCluster.getDistanceCost(nodeList[0], nodeList[0]));
    assertEquals(2, newCluster.getDistanceCost(nodeList[0], nodeList[1]));
    assertEquals(8, newCluster.getDistanceCost(nodeList[0], nodeList[2]));
    assertEquals(18, newCluster.getDistanceCost(nodeList[0], nodeList[3]));
}

@Test
public void testSortByDistanceCost() {
    Node[][] nodes = { {}, { dataNodes[0] }, { dataNodes[dataNodes.length - 1] }, { dataNodes[random.nextInt(dataNodes.length)] }, { dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)] }, { dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)] }, { dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)] }, { dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)] } };
    Node[] readers = { null, dataNodes[0], dataNodes[dataNodes.length - 1], dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)] };
    for (Node reader : readers) {
        for (Node[] nodeList : nodes) {
            int length = nodeList.length;
            while (length > 0) {
                cluster.sortByDistanceCost(reader, nodeList, length);
                for (int i = 0; i < nodeList.length; i++) {
                    if ((i + 1) < nodeList.length) {
                        int cost1 = cluster.getDistanceCost(reader, nodeList[i]);
                        int cost2 = cluster.getDistanceCost(reader, nodeList[i + 1]);
                        assertTrue("reader:" + (reader != null ? reader.getNetworkFullPath() : "null") + ",node1:" + nodeList[i].getNetworkFullPath() + ",node2:" + nodeList[i + 1].getNetworkFullPath() + ",cost1:" + cost1 + ",cost2:" + cost2, cost1 == Integer.MAX_VALUE || cost1 <= cost2);
                    }
                }
                length--;
            }
        }
    }
    // sort all nodes
    Node[] nodeList = dataNodes.clone();
    for (Node reader : readers) {
        int length = nodeList.length;
        while (length >= 0) {
            cluster.sortByDistanceCost(reader, nodeList, length);
            for (int i = 0; i < nodeList.length; i++) {
                if ((i + 1) < nodeList.length) {
                    int cost1 = cluster.getDistanceCost(reader, nodeList[i]);
                    int cost2 = cluster.getDistanceCost(reader, nodeList[i + 1]);
                    // node can be removed when called in testConcurrentAccess
                    assertTrue("reader:" + (reader != null ? reader.getNetworkFullPath() : "null") + ",node1:" + nodeList[i].getNetworkFullPath() + ",node2:" + nodeList[i + 1].getNetworkFullPath() + ",cost1:" + cost1 + ",cost2:" + cost2, cost1 == Integer.MAX_VALUE || cost1 <= cost2);
                }
            }
            length--;
        }
    }
}

