        if (containerId % 2 == 0) {
            assertEquals(ContainerProtos.ContainerDataProto.State.CLOSED, containerData.getState());
        } else {
            assertEquals(ContainerProtos.ContainerDataProto.State.OPEN, containerData.getState());
        }
        count++;
    }
    assertEquals(10, count);
