    assertTrue(keyValueBlockIterator.hasNext());
    assertTrue(keyValueBlockIterator.hasNext());
    assertTrue(keyValueBlockIterator.hasNext());
    assertEquals(blockID, keyValueBlockIterator.nextBlock().getLocalID());
    keyValueBlockIterator.seekToLast();
    assertTrue(keyValueBlockIterator.hasNext());
    assertEquals(blockID, keyValueBlockIterator.nextBlock().getLocalID());
    keyValueBlockIterator.seekToFirst();
    blockID = 0L;
    assertEquals(blockID++, keyValueBlockIterator.nextBlock().getLocalID());
    assertEquals(blockID, keyValueBlockIterator.nextBlock().getLocalID());
    try {
        keyValueBlockIterator.nextBlock();
