/**
 * Sanity test, when there are no corruptions induced.
 * @throws Exception
 */
@Test
public void testKeyValueContainerCheckNoCorruption() throws Exception {
    long containerID = 101;
    int deletedBlocks = 1;
    int normalBlocks = 3;
    int chunksPerBlock = 4;
    boolean corruption = false;
    // test Closed Container
    createContainerWithBlocks(containerID, normalBlocks, deletedBlocks, 65536, chunksPerBlock);
    File chunksPath = new File(containerData.getChunksPath());
    assertTrue(chunksPath.listFiles().length == (deletedBlocks + normalBlocks) * chunksPerBlock);
    KeyValueContainerCheck kvCheck = new KeyValueContainerCheck(containerData.getMetadataPath(), conf, containerID);
    // first run checks on a Open Container
    corruption = kvCheck.fastCheck();
    assertFalse(corruption);
    container.close();
    // next run checks on a Closed Container
    corruption = kvCheck.fullCheck();
    assertFalse(corruption);
}

