@Test
public void testEventHandling() throws InterruptedException {
    EventQueue queue = new EventQueue();
    EventWatcher<UnderreplicatedEvent, ReplicationCompletedEvent> replicationWatcher = createEventWatcher();
    EventHandlerStub<UnderreplicatedEvent> underReplicatedEvents = new EventHandlerStub<>();
    queue.addHandler(UNDER_REPLICATED, underReplicatedEvents);
    replicationWatcher.start(queue);
    long id1 = HddsIdFactory.getLongId();
    long id2 = HddsIdFactory.getLongId();
    queue.fireEvent(WATCH_UNDER_REPLICATED, new UnderreplicatedEvent(id1, "C1"));
    queue.fireEvent(WATCH_UNDER_REPLICATED, new UnderreplicatedEvent(id2, "C2"));
    Assert.assertEquals(0, underReplicatedEvents.getReceivedEvents().size());
    Thread.sleep(1000);
    queue.fireEvent(REPLICATION_COMPLETED, new ReplicationCompletedEvent(id1, "C2", "D1"));
    Assert.assertEquals(0, underReplicatedEvents.getReceivedEvents().size());
    Thread.sleep(1500);
    queue.processAll(1000L);
    Assert.assertEquals(1, underReplicatedEvents.getReceivedEvents().size());
    Assert.assertEquals(id2, underReplicatedEvents.getReceivedEvents().get(0).id);
}

@Test
public void testInprogressFilter() throws InterruptedException {
    EventQueue queue = new EventQueue();
    EventWatcher<UnderreplicatedEvent, ReplicationCompletedEvent> replicationWatcher = createEventWatcher();
    EventHandlerStub<UnderreplicatedEvent> underReplicatedEvents = new EventHandlerStub<>();
    queue.addHandler(UNDER_REPLICATED, underReplicatedEvents);
    replicationWatcher.start(queue);
    UnderreplicatedEvent event1 = new UnderreplicatedEvent(HddsIdFactory.getLongId(), "C1");
    queue.fireEvent(WATCH_UNDER_REPLICATED, event1);
    queue.fireEvent(WATCH_UNDER_REPLICATED, new UnderreplicatedEvent(HddsIdFactory.getLongId(), "C2"));
    queue.fireEvent(WATCH_UNDER_REPLICATED, new UnderreplicatedEvent(HddsIdFactory.getLongId(), "C1"));
    queue.processAll(1000L);
    Thread.sleep(1000L);
    List<UnderreplicatedEvent> c1todo = replicationWatcher.getTimeoutEvents(e -> e.containerId.equalsIgnoreCase("C1"));
    Assert.assertEquals(2, c1todo.size());
