/**
 * If the container is in CLOSING state we resend close container command
 * to all the datanodes.
 */
@Test
public void testClosingContainer() throws SCMException, ContainerNotFoundException, InterruptedException {
    final ContainerInfo container = getContainer(LifeCycleState.CLOSING);
    final ContainerID id = container.containerID();
    containerStateManager.loadContainer(container);
    // Two replicas in CLOSING state
    final Set<ContainerReplica> replicas = getReplicas(id, State.CLOSING, randomDatanodeDetails(), randomDatanodeDetails());
    // One replica in OPEN state
    final DatanodeDetails datanode = randomDatanodeDetails();
    replicas.addAll(getReplicas(id, State.OPEN, datanode));
    for (ContainerReplica replica : replicas) {
        containerStateManager.updateContainerReplica(id, replica);
    }
    final int currentCloseCommandCount = datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.closeContainerCommand);
    replicationManager.processContainersNow();
    // Wait for EventQueue to call the event handler
    Thread.sleep(100L);
    Assert.assertEquals(currentCloseCommandCount + 3, datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.closeContainerCommand));
    // Update the OPEN to CLOSING
    for (ContainerReplica replica : getReplicas(id, State.CLOSING, datanode)) {
        containerStateManager.updateContainerReplica(id, replica);
    }
    replicationManager.processContainersNow();
    // Wait for EventQueue to call the event handler
    Thread.sleep(100L);
    Assert.assertEquals(currentCloseCommandCount + 6, datanodeCommandHandler.getInvocationCount(SCMCommandProto.Type.closeContainerCommand));
}

