@Test
public void testCreatePipelinesDnExclude() throws IOException {
    // We have 10 DNs in MockNodeManager.
    // Use up first 3 DNs for an open pipeline.
    List<DatanodeDetails> openPiplineDns = nodeManager.getAllNodes().subList(0, 3);
    HddsProtos.ReplicationFactor factor = HddsProtos.ReplicationFactor.THREE;
    Pipeline openPipeline = Pipeline.newBuilder().setType(HddsProtos.ReplicationType.RATIS).setFactor(factor).setNodes(openPiplineDns).setState(Pipeline.PipelineState.OPEN).setId(PipelineID.randomId()).build();
    stateManager.addPipeline(openPipeline);
    // Use up next 3 DNs also for an open pipeline.
    List<DatanodeDetails> moreOpenPiplineDns = nodeManager.getAllNodes().subList(3, 6);
    Pipeline anotherOpenPipeline = Pipeline.newBuilder().setType(HddsProtos.ReplicationType.RATIS).setFactor(factor).setNodes(moreOpenPiplineDns).setState(Pipeline.PipelineState.OPEN).setId(PipelineID.randomId()).build();
    stateManager.addPipeline(anotherOpenPipeline);
    // Use up next 3 DNs also for a closed pipeline.
    List<DatanodeDetails> closedPiplineDns = nodeManager.getAllNodes().subList(6, 9);
    Pipeline anotherClosedPipeline = Pipeline.newBuilder().setType(HddsProtos.ReplicationType.RATIS).setFactor(factor).setNodes(closedPiplineDns).setState(Pipeline.PipelineState.CLOSED).setId(PipelineID.randomId()).build();
    stateManager.addPipeline(anotherClosedPipeline);
    Pipeline pipeline = provider.create(factor);
    Assert.assertEquals(pipeline.getType(), HddsProtos.ReplicationType.RATIS);
    Assert.assertEquals(pipeline.getFactor(), factor);
    Assert.assertEquals(pipeline.getPipelineState(), Pipeline.PipelineState.OPEN);
    Assert.assertEquals(pipeline.getNodes().size(), factor.getNumber());
    List<DatanodeDetails> pipelineNodes = pipeline.getNodes();
    // Pipline nodes cannot be from open pipelines.
    Assert.assertTrue(pipelineNodes.parallelStream().filter(dn -> (openPiplineDns.contains(dn) || moreOpenPiplineDns.contains(dn))).count() == 0);
    // Since we have only 10 DNs, at least 1 pipeline node should have been
    // from the closed pipeline DN list.
    Assert.assertTrue(pipelineNodes.parallelStream().filter(closedPiplineDns::contains).count() > 0);
}

