/**
 * Tests reading a corrputed chunk file throws checksum exception.
 * @throws IOException
 */
@Test
public void testHybridPipelineOnDatanode() throws IOException {
    String volumeName = UUID.randomUUID().toString();
    String bucketName = UUID.randomUUID().toString();
    String value = UUID.randomUUID().toString();
    byte[] data = value.getBytes();
    objectStore.createVolume(volumeName);
    OzoneVolume volume = objectStore.getVolume(volumeName);
    volume.createBucket(bucketName);
    OzoneBucket bucket = volume.getBucket(bucketName);
    String keyName1 = UUID.randomUUID().toString();
    // Write data into a key
    OzoneOutputStream out = bucket.createKey(keyName1, data.length, ReplicationType.RATIS, ReplicationFactor.ONE, new HashMap<>());
    out.write(value.getBytes());
    out.close();
    String keyName2 = UUID.randomUUID().toString();
    // Write data into a key
    out = bucket.createKey(keyName2, data.length, ReplicationType.RATIS, ReplicationFactor.THREE, new HashMap<>());
    out.write(value.getBytes());
    out.close();
    // We need to find the location of the chunk file corresponding to the
    // data we just wrote.
    OzoneKey key1 = bucket.getKey(keyName1);
    long containerID1 = ((OzoneKeyDetails) key1).getOzoneKeyLocations().get(0).getContainerID();
    OzoneKey key2 = bucket.getKey(keyName2);
    long containerID2 = ((OzoneKeyDetails) key2).getOzoneKeyLocations().get(0).getContainerID();
    PipelineID pipelineID1 = cluster.getStorageContainerManager().getContainerInfo(containerID1).getPipelineID();
    PipelineID pipelineID2 = cluster.getStorageContainerManager().getContainerInfo(containerID2).getPipelineID();
    Pipeline pipeline1 = cluster.getStorageContainerManager().getPipelineManager().getPipeline(pipelineID1);
    List<DatanodeDetails> dns = pipeline1.getNodes();
    Assert.assertTrue(dns.size() == 1);
    Pipeline pipeline2 = cluster.getStorageContainerManager().getPipelineManager().getPipeline(pipelineID2);
    Assert.assertFalse(pipeline1.getFactor().equals(pipeline2.getFactor()));
    Assert.assertTrue(pipeline1.getType() == HddsProtos.ReplicationType.RATIS);
    Assert.assertTrue(pipeline1.getType() == pipeline2.getType());
    // assert that the pipeline Id1 and pipelineId2 are on the same node
    // but different replication factor
    Assert.assertTrue(pipeline2.getNodes().contains(dns.get(0)));
    byte[] b1 = new byte[data.length];
    byte[] b2 = new byte[data.length];
    // now try to read both the keys
    OzoneInputStream is = bucket.readKey(keyName1);
    is.read(b1);
    is.close();
    // now try to read both the keys
    is = bucket.readKey(keyName2);
    is.read(b2);
    is.close();
    Assert.assertTrue(Arrays.equals(b1, data));
    Assert.assertTrue(Arrays.equals(b1, b2));
}

@Test
public void testSeek() throws Exception {
    XceiverClientMetrics metrics = XceiverClientManager.getXceiverClientMetrics();
    long writeChunkCount = metrics.getContainerOpCountMetrics(ContainerProtos.Type.WriteChunk);
    long readChunkCount = metrics.getContainerOpCountMetrics(ContainerProtos.Type.ReadChunk);
    String keyName = getKeyName();
    OzoneOutputStream key = ContainerTestHelper.createKey(keyName, ReplicationType.RATIS, 0, objectStore, volumeName, bucketName);
    // write data spanning 3 chunks
    int dataLength = (2 * chunkSize) + (chunkSize / 2);
    byte[] inputData = ContainerTestHelper.getFixedLengthString(keyString, dataLength).getBytes(UTF_8);
    key.write(inputData);
    key.close();
    Assert.assertEquals(writeChunkCount + 3, metrics.getContainerOpCountMetrics(ContainerProtos.Type.WriteChunk));
    KeyInputStream keyInputStream = (KeyInputStream) objectStore.getVolume(volumeName).getBucket(bucketName).readKey(keyName).getInputStream();
    // Seek to position 150
    keyInputStream.seek(150);
    Assert.assertEquals(150, keyInputStream.getPos());
    // Seek operation should not result in any readChunk operation.
    Assert.assertEquals(readChunkCount, metrics.getContainerOpsMetrics(ContainerProtos.Type.ReadChunk));
    Assert.assertEquals(readChunkCount, metrics.getContainerOpCountMetrics(ContainerProtos.Type.ReadChunk));
    byte[] readData = new byte[chunkSize];
    keyInputStream.read(readData, 0, chunkSize);
    // Since we reading data from index 150 to 250 and the chunk boundary is
    // 100 bytes, we need to read 2 chunks.
    Assert.assertEquals(readChunkCount + 2, metrics.getContainerOpCountMetrics(ContainerProtos.Type.ReadChunk));
    keyInputStream.close();
    // Verify that the data read matches with the input data at corresponding
    // indices.
    for (int i = 0; i < chunkSize; i++) {
        Assert.assertEquals(inputData[chunkSize + 50 + i], readData[i]);
    }
}

