@Test
public void testUpdateOmDB() throws Exception {
    //Create a new OM Metadata Manager instance + DB.
    File omDbDir = temporaryFolder.newFolder();
    OzoneConfiguration omConfiguration = new OzoneConfiguration();
    omConfiguration.set(OZONE_OM_DB_DIRS, omDbDir.getAbsolutePath());
    OMMetadataManager omMetadataManager = new OmMetadataManagerImpl(omConfiguration);
    //Create a volume + bucket + 2 keys.
    String volumeKey = omMetadataManager.getVolumeKey("sampleVol");
    OmVolumeArgs args = OmVolumeArgs.newBuilder().setVolume("sampleVol").setAdminName("TestUser").setOwnerName("TestUser").build();
    omMetadataManager.getVolumeTable().put(volumeKey, args);
    BucketManager bucketManager = new BucketManagerImpl(omMetadataManager);
    OmBucketInfo bucketInfo = OmBucketInfo.newBuilder().setVolumeName("sampleVol").setBucketName("bucketOne").build();
    bucketManager.createBucket(bucketInfo);
    omMetadataManager.getKeyTable().put("/sampleVol/bucketOne/key_one", new OmKeyInfo.Builder().setBucketName("bucketOne").setVolumeName("sampleVol").setKeyName("key_one").setReplicationFactor(HddsProtos.ReplicationFactor.ONE).setReplicationType(HddsProtos.ReplicationType.STAND_ALONE).build());
    omMetadataManager.getKeyTable().put("/sampleVol/bucketOne/key_two", new OmKeyInfo.Builder().setBucketName("bucketOne").setVolumeName("sampleVol").setKeyName("key_two").setReplicationFactor(HddsProtos.ReplicationFactor.ONE).setReplicationType(HddsProtos.ReplicationType.STAND_ALONE).build());
    //Make sure OM Metadata reflects the keys that were inserted.
    Assert.assertNotNull(omMetadataManager.getKeyTable().get("/sampleVol/bucketOne/key_one"));
    Assert.assertNotNull(omMetadataManager.getKeyTable().get("/sampleVol/bucketOne/key_two"));
    //Take checkpoint of OM DB.
    DBCheckpoint checkpoint = omMetadataManager.getStore().getCheckpoint(true);
    Assert.assertNotNull(checkpoint.getCheckpointLocation());
    //Create new Recon OM Metadata manager instance.
    File reconOmDbDir = temporaryFolder.newFolder();
    OzoneConfiguration configuration = new OzoneConfiguration();
    configuration.set(OZONE_RECON_OM_SNAPSHOT_DB_DIR, reconOmDbDir.getAbsolutePath());
    ReconOMMetadataManager reconOMMetadataManager = new ReconOmMetadataManagerImpl(configuration);
    reconOMMetadataManager.start(configuration);
    //Before accepting a snapshot, the metadata should have null tables.
    Assert.assertNull(reconOMMetadataManager.getBucketTable());
    //Update Recon OM DB with the OM DB checkpoint location.
    reconOMMetadataManager.updateOmDB(checkpoint.getCheckpointLocation().toFile());
    //Now, the tables should have been initialized.
    Assert.assertNotNull(reconOMMetadataManager.getBucketTable());
    //Verify Keys inserted in OM DB are available in Recon OM DB.
    Assert.assertNotNull(reconOMMetadataManager.getKeyTable().get("/sampleVol/bucketOne/key_one"));
    Assert.assertNotNull(reconOMMetadataManager.getKeyTable().get("/sampleVol/bucketOne/key_two"));
    //Verify that we cannot write data to Recon OM DB (Read Only)
    try {
        reconOMMetadataManager.getKeyTable().put("/sampleVol/bucketOne/fail_key", new OmKeyInfo.Builder().setBucketName("bucketOne").setVolumeName("sampleVol").setKeyName("fail_key").setReplicationFactor(HddsProtos.ReplicationFactor.ONE).setReplicationType(HddsProtos.ReplicationType.STAND_ALONE).build());
        Assert.fail();
    } catch (IOException e) {
        Assert.assertTrue(e.getMessage().contains("Not supported operation in read only mode"));
    }
}

