@Test
public void singlechunk() throws IOException {
    //test simple read()
    InputStream is = fileContent("0A;chunk-signature" + "=23abb2bd920ddeeaac78a63ed808bc59fa6e7d3ef0e356474b82cdc2f8c93c40\r" + "\n1234567890\r\n");
    String result = IOUtils.toString(is, Charset.forName("UTF-8"));
    Assert.assertEquals("1234567890", result);
    //test read(byte[],int,int)
    is = fileContent("0A;chunk-signature" + "=23abb2bd920ddeeaac78a63ed808bc59fa6e7d3ef0e356474b82cdc2f8c93c40\r" + "\n1234567890\r\n");
    byte[] bytes = new byte[10];
    IOUtils.read(is, bytes, 0, 10);
    Assert.assertEquals("1234567890", new String(bytes));
}

